/**
 * Writes scripts/data/diabetes-market-research-uae-2026-price-cuts.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-diabetes-uae-price-cuts-cover.mjs.
 *
 *   node scripts/generate-diabetes-uae-price-cuts-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/diabetes-market-research-uae-2026-price-cuts.json');

export const MARTHA_DEVITO_SANITY_ID = '6263dcc8-994f-4cd1-9228-7e92332659d3';

/** Every blogPost field that applies to a healthcare-silo article. */
export const DIABETES_UAE_CUTS_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-diabetes-market-research-uae-2026-price-cuts.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.DIABETES_UAE_CUTS_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.DIABETES_UAE_CUTS_BODY_HTML.split('<h2')[0])
    .replace(/^Diabetes market research UAE[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.DIABETES_UAE_CUTS_META_TITLE,
      metaDescription: mod.DIABETES_UAE_CUTS_META_DESCRIPTION,
      focusKeyword: 'diabetes market research UAE',
      keywords: [
        'diabetes market research UAE',
        'Emirates Drug Establishment',
        'EDE Decision 12 2026',
        'UAE diabetes price cut',
        'Type 2 diabetes UAE',
        'UAE drug pricing',
        'UAE market access research',
        'Amaryl UAE price',
      ],
      canonicalUrl: mod.DIABETES_UAE_CUTS_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.DIABETES_UAE_CUTS_META_TITLE,
      ogDescription: mod.DIABETES_UAE_CUTS_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.DIABETES_UAE_CUTS_COVER_IMAGE}`,
        alt: mod.DIABETES_UAE_CUTS_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.DIABETES_UAE_CUTS_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.DIABETES_UAE_CUTS_SLUG },
    excerpt: mod.DIABETES_UAE_CUTS_EXCERPT,
    publishedAt: mod.DIABETES_UAE_CUTS_PUBLISHED_ISO,
    updatedAt: mod.DIABETES_UAE_CUTS_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: MARTHA_DEVITO_SANITY_ID,
      name: 'Martha DeVito',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.DIABETES_UAE_CUTS_HERO_IMAGE}`,
      alt: mod.DIABETES_UAE_CUTS_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for diabetes market research UAE after the 2026 price cuts',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.DIABETES_UAE_CUTS_TAGS],
    country: 'United Arab Emirates',
    language: 'en',
    readingTime: mod.DIABETES_UAE_CUTS_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.DIABETES_UAE_CUTS_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.DIABETES_UAE_CUTS_EXECUTIVE_SUMMARY_HTML}\n\n${mod.DIABETES_UAE_CUTS_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What diabetes market research UAE should measure after the 2026 price cuts',
        type: 'table',
        data: JSON.stringify(
          mod.DIABETES_UAE_CUTS_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'Gulf News 26 May 2026; MOHAP 5 January 2026; IDF Atlas 11th; DoH Circular 188/2025',
      },
      portableText(
        firstParagraph ||
          'Diabetes market research UAE is a pricing, switching and listing problem again, not only an epidemiology slide.',
      ),
    ],
    faq: mod.DIABETES_UAE_CUTS_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: [
      'uae-drug-pricing-ede-takeover-launch-research',
      'oral-glp-1-uae-market-research',
      'gcc-pharmacoeconomics',
    ],
    ctaSection: { ...mod.DIABETES_UAE_CUTS_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.DIABETES_UAE_CUTS_BODY_HTML),
    factCheckedAt: mod.DIABETES_UAE_CUTS_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/diabetes-market-research-uae-2026-price-cuts-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of DIABETES_UAE_CUTS_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(
    `Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`,
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
